//! Mandarin text → Kokoro v1.0 phonemes.
//!
//! A port of misaki's legacy Chinese G2P, which the v1.0 `zf_*`/`zm_*`
//! voices were trained on: split Han runs into words with jieba, read each
//! word with pypinyin's rules (phrase readings first, then each character's
//! default), and map every pinyin syllable to Kokoro's IPA with tone arrows.
//!
//! The lookup tables are generated by `scripts/gen_kokoro_zh_data.py` from
//! pypinyin (MIT; data from mozillazg/pinyin-data and phrase-pinyin-data,
//! MIT) and misaki (Apache-2.0; syllable mapping adapted from
//! stefantaubert/pinyin-to-ipa, MIT).

use std::collections::{HashMap, HashSet};

use jieba_rs::Jieba;

const CHARS: &str = include_str!("chars.tsv");
const PHRASES: &str = include_str!("phrases.tsv");
const SYLLABLES: &str = include_str!("syllables.tsv");

/// Han characters the Mandarin path reads (misaki's range).
pub(crate) fn is_han(c: char) -> bool {
    ('\u{4E00}'..='\u{9FFF}').contains(&c)
}

/// Any Chinese character, including rare ones the tables don't cover.
/// These mark text as Chinese and stay in Han runs, so an unknown one is
/// skipped (as misaki does) rather than handed to the English G2P.
pub(crate) fn is_cjk(c: char) -> bool {
    is_han(c)
        || c == '〇'
        || ('\u{3400}'..='\u{4DBF}').contains(&c) // Extension A
        || ('\u{F900}'..='\u{FAFF}').contains(&c) // Compatibility ideographs
        || ('\u{20000}'..='\u{3134F}').contains(&c) // Extensions B–G
}

/// Mandarin G2P. Building it loads jieba's dictionary, so create it once
/// and only when Chinese text shows up.
pub(super) struct Mandarin {
    jieba: Jieba,
    chars: HashMap<char, &'static str>,
    /// Every pypinyin phrase; `Some` only where its reading differs from
    /// reading each character on its own.
    phrases: HashMap<&'static str, Option<&'static str>>,
    /// All prefixes of all phrases, for pypinyin's forward matching.
    prefixes: HashSet<&'static str>,
    syllables: HashMap<&'static str, &'static str>,
}

impl Mandarin {
    pub(super) fn new() -> Self {
        let mut chars: HashMap<char, &'static str> = CHARS
            .lines()
            .filter_map(|l| {
                let (c, r) = l.split_once('\t')?;
                Some((c.chars().next()?, r))
            })
            .collect();
        // Zero, as in 二〇二四年; outside misaki's range but common.
        chars.insert('〇', "ling2");
        let mut phrases = HashMap::new();
        let mut prefixes = HashSet::new();
        for line in PHRASES.lines() {
            let (word, reading) = match line.split_once('\t') {
                Some((w, r)) => (w, Some(r)),
                None => (line, None),
            };
            phrases.insert(word, reading);
            for (i, c) in word.char_indices() {
                prefixes.insert(&word[..i + c.len_utf8()]);
            }
        }
        let syllables = SYLLABLES
            .lines()
            .filter_map(|l| l.split_once('\t'))
            .collect();
        Self {
            jieba: Jieba::new(),
            chars,
            phrases,
            prefixes,
            syllables,
        }
    }

    /// Phonemes for one sentence that already went through
    /// [`map_punctuation`]. Han runs are read as Mandarin; runs with
    /// letters or digits go to `english`; punctuation passes through.
    pub(super) fn phonemize(&self, text: &str, english: impl Fn(&str) -> String) -> String {
        let mut out = String::new();
        for (han, run) in runs(text) {
            if han {
                let words: Vec<String> = self
                    .jieba
                    .cut(run, true)
                    .into_iter()
                    .map(|t| self.word(t.word))
                    .collect();
                out.push_str(&words.join(" "));
            } else if run.chars().any(|c| c.is_alphanumeric()) {
                let lead = &run[..run.len() - run.trim_start().len()];
                let trail = &run[run.trim_end().len()..];
                out.push_str(lead);
                out.push_str(&english(run.trim()));
                out.push_str(trail);
            } else {
                out.push_str(run);
            }
        }
        out
    }

    /// One jieba word: pypinyin's forward matching against its phrase
    /// prefixes, then each piece's phrase or per-character reading.
    fn word(&self, word: &str) -> String {
        let mut out = String::new();
        let mut rest = word;
        while !rest.is_empty() {
            let mut cut = 0;
            for (i, c) in rest.char_indices() {
                let end = i + c.len_utf8();
                if self.prefixes.contains(&rest[..end]) {
                    cut = end;
                } else {
                    break;
                }
            }
            if cut == 0 {
                cut = rest.chars().next().map_or(rest.len(), char::len_utf8);
            }
            let (piece, tail) = rest.split_at(cut);
            match self.phrases.get(piece) {
                Some(Some(reading)) => reading.split(' ').for_each(|r| self.push(&mut out, r)),
                _ => piece
                    .chars()
                    .filter_map(|c| self.chars.get(&c))
                    .for_each(|r| self.push(&mut out, r)),
            }
            rest = tail;
        }
        out
    }

    fn push(&self, out: &mut String, reading: &str) {
        if let Some(ipa) = self.syllables.get(reading) {
            out.push_str(ipa);
        }
    }
}

/// Map Chinese punctuation to the ASCII forms Kokoro was trained on.
pub(super) fn map_punctuation(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '、' | '，' => out.push_str(", "),
            '。' | '．' => out.push_str(". "),
            '！' => out.push_str("! "),
            '：' => out.push_str(": "),
            '；' => out.push_str("; "),
            '？' => out.push_str("? "),
            '«' | '《' | '「' | '【' => out.push_str(" “"),
            '»' | '》' | '」' | '】' => out.push_str("” "),
            '（' => out.push_str(" ("),
            '）' => out.push_str(") "),
            _ => out.push(c),
        }
    }
    out.trim().to_string()
}

/// Split into alternating Han / non-Han runs.
fn runs(text: &str) -> Vec<(bool, &str)> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut current: Option<bool> = None;
    for (i, c) in text.char_indices() {
        let han = is_cjk(c);
        if current.is_some_and(|h| h != han) {
            out.push((current.unwrap(), &text[start..i]));
            start = i;
        }
        current = Some(han);
    }
    if let Some(h) = current {
        out.push((h, &text[start..]));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Matches misaki's own output, generated alongside the tables.
    #[test]
    fn matches_misaki_golden_sentences() {
        let zh = Mandarin::new();
        let mut failures = Vec::new();
        for line in include_str!("golden.tsv").lines() {
            let (text, want) = line.split_once('\t').unwrap();
            let got = zh.phonemize(&map_punctuation(text), |_| String::new());
            if got != want {
                failures.push(format!("{text}\n  want {want}\n  got  {got}"));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

    #[test]
    fn phrases_fix_polyphones() {
        let zh = Mandarin::new();
        // 重庆 is chóng, not the default zhòng; 银行 is háng, not xíng.
        assert!(zh.word("重庆").starts_with("ꭧʰʊ↗ŋ"));
        assert!(zh.word("银行").ends_with("xa↗ŋ"));
        // Neutral tone from the phrase table.
        assert_eq!(zh.word("我们"), "wo↓mən");
        assert!(zh.word("〇").starts_with('l'));
    }

    #[test]
    fn latin_runs_go_to_english() {
        let zh = Mandarin::new();
        let out = zh.phonemize("请打开 Wi-Fi 设置", |en| format!("<{en}>"));
        assert!(out.contains(" <Wi-Fi> "), "{out}");
    }

    #[test]
    fn punctuation_maps_to_ascii() {
        assert_eq!(map_punctuation("你好，世界。"), "你好, 世界.");
        assert_eq!(map_punctuation("《书》"), "“书”");
    }

    #[test]
    fn runs_alternate() {
        assert_eq!(
            runs("你好 ok 世界"),
            vec![(true, "你好"), (false, " ok "), (true, "世界")]
        );
        assert_eq!(runs("二〇二四"), vec![(true, "二〇二四")]);
        assert!(runs("").is_empty());
    }
}
